functions._tsState:
function _tsState() {
  if (!window._tsSearcherState) {
    window._tsSearcherState = {
      templates: null,        // [{id, name, content, byteLength, compressed}]
      loadedAt: 0,
      loadPromise: null,
      history: [],            // [{query, opts, ts, hitCount}], max 5
      CACHE_TTL_MS: 5 * 60 * 1000,
    };
  }
  return window._tsSearcherState;
}

functions._tsBdDecompress:
function _tsBdDecompress(rec) {
  if (!rec || !rec._z) return rec;
  if (!window.pako || typeof window.pako.inflate !== "function") {
    return Object.assign({}, rec, {
      content: "[ERROR: template compressed but pako not loaded. " +
        "Add https://cdn.jsdelivr.net/npm/pako@2.1.0/dist/pako.min.js to Script Lab Libraries.]",
      _decompressError: true,
    });
  }
  try {
    var bytes = rec.content;
    var compressedBytes = (bytes && bytes.byteLength) || 0;
    var utf8 = window.pako.inflate(bytes);
    var str = new TextDecoder().decode(utf8);
    return Object.assign({}, rec, {
      content: str,
      _decompressedBytes: compressedBytes,
      _originalLen: rec._origLen || str.length,
    });
  } catch (e) {
    return Object.assign({}, rec, {
      content: "[ERROR decoding compressed template: " + (e && e.message || e) + "]",
      _decompressError: true,
    });
  }
}

functions.tsLoadTemplates:
function tsLoadTemplates(force) {
  var s = (function () {
    if (!window._tsSearcherState) {
      window._tsSearcherState = { templates: null, loadedAt: 0, loadPromise: null, history: [], CACHE_TTL_MS: 5 * 60 * 1000 };
    }
    return window._tsSearcherState;
  })();
  if (!force && s.templates && (Date.now() - s.loadedAt) < s.CACHE_TTL_MS) {
    return Promise.resolve(s.templates);
  }
  if (s.loadPromise) return s.loadPromise;
  function _bdDecompress(rec) {
    if (!rec || !rec._z) return rec;
    if (!window.pako || typeof window.pako.inflate !== "function") {
      return Object.assign({}, rec, {
        content: "[ERROR: template compressed but pako not loaded. Add https://cdn.jsdelivr.net/npm/pako@2.1.0/dist/pako.min.js to Script Lab Libraries.]",
        _decompressError: true,
      });
    }
    try {
      var bytes = rec.content;
      var compressedBytes = (bytes && bytes.byteLength) || 0;
      var utf8 = window.pako.inflate(bytes);
      var str = new TextDecoder().decode(utf8);
      return Object.assign({}, rec, {
        content: str,
        _decompressedBytes: compressedBytes,
        _originalLen: rec._origLen || str.length,
      });
    } catch (e) {
      return Object.assign({}, rec, {
        content: "[ERROR decoding compressed template: " + (e && e.message || e) + "]",
        _decompressError: true,
      });
    }
  }
  // 2026-05-23: bd_templates content is raw Word OOXML — `<w:p>` paragraph
  // wrappers, `<w:r>` runs, `<w:t>` text spans, plus dozens of formatting
  // attributes. Search and clause display need PLAIN text. Strip via
  // regex (full XML parser would be overkill for a heuristic search UI):
  //   - paragraph close → double newline
  //   - tab marker → \t
  //   - line break → \n
  //   - text span → inner text only
  //   - any other tag → drop
  //   - decode standard entities
  //   - collapse runs of 3+ newlines to 2
  // Falls through to identity for non-OOXML rows (some templates may be
  // plain text already).
  function _ooxmlToPlainText(xml) {
    if (!xml) return "";
    var s = String(xml);
    var head = s.slice(0, 300);
    var looksLikeOoxml = /<w:[a-z]+/.test(head) || head.indexOf("<?xml") !== -1;
    if (!looksLikeOoxml) return s;
    return s
      .replace(/<w:p[^>]*\/>/g, "\n\n")
      .replace(/<\/w:p>/g, "\n\n")
      .replace(/<w:tab[^>]*\/>/g, "\t")
      .replace(/<w:br[^>]*\/>/g, "\n")
      .replace(/<w:t[^>]*>([\s\S]*?)<\/w:t>/g, "$1")
      .replace(/<[^>]+>/g, "")
      .replace(/&amp;/g, "&")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&#(\d+);/g, function (_, n) { return String.fromCharCode(parseInt(n, 10)); })
      .replace(/\n{3,}/g, "\n\n")
      .replace(/[ \t]{2,}/g, " ")
      .trim();
  }
  s.loadPromise = window.eli.storage.getAll("bd_templates").then(function (rows) {
    var clean = (rows || []).filter(function (r) {
      return r && r.id && String(r.id).charAt(0) !== "_";
    }).map(function (r) {
      var decomp = _bdDecompress(r);
      var rawContent = String(decomp.content || "");
      var plain = _ooxmlToPlainText(rawContent);
      return {
        id: decomp.id,
        name: decomp.name || decomp.title || decomp.id,
        category: decomp.category || decomp.agreementType || "",
        // `content` is now the cleaned plain text — what search/display
        // operates on. `rawContent` is preserved for future use (e.g.,
        // "open in Build Draft" needs the original OOXML).
        content: plain,
        rawContent: rawContent,
        length: plain.length,
        rawLength: rawContent.length,
        isOoxml: plain !== rawContent,
        compressed: !!r._z,
        compressedBytes: decomp._decompressedBytes || 0,
        decompressError: !!decomp._decompressError,
        updatedAt: decomp.updatedAt || decomp.lastModified || null,
      };
    }).sort(function (a, b) {
      return String(a.name).localeCompare(String(b.name));
    });
    s.templates = clean;
    s.loadedAt = Date.now();
    s.loadPromise = null;
    return clean;
  }).catch(function (err) {
    s.loadPromise = null;
    throw err;
  });
  return s.loadPromise;
}

// Run search. Returns { templates: [{id, name, hits: [{index, snippet}], totalHits}], totalHits }.
// opts: { caseSensitive, wholeWord, contextChars }

functions.tsSearch:
function tsSearch(templates, query, opts) {
  opts = opts || {};
  var ctxChars = opts.contextChars || 90;
  if (!query) return { templates: [], totalHits: 0 };
  // Build a regex for the search — escapes special chars then optionally
  // wraps in \b...\b for whole-word matching. Case sensitivity controls
  // the 'i' flag.
  var escaped = String(query).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  var pattern = opts.wholeWord ? "\\b" + escaped + "\\b" : escaped;
  var flags = "g" + (opts.caseSensitive ? "" : "i");
  var re;
  try { re = new RegExp(pattern, flags); }
  catch (e) { return { templates: [], totalHits: 0, error: e.message }; }
  var totalHits = 0;
  var results = [];
  templates.forEach(function (t) {
    if (!t.content || t.decompressError) return;
    var hits = [];
    var match;
    re.lastIndex = 0;
    while ((match = re.exec(t.content)) !== null) {
      var idx = match.index;
      var matchLen = match[0].length;
      var startCtx = Math.max(0, idx - ctxChars);
      var endCtx = Math.min(t.content.length, idx + matchLen + ctxChars);
      // Expand to nearest space on each side so we don't cut a word.
      while (startCtx > 0 && /\S/.test(t.content.charAt(startCtx - 1)) && (idx - startCtx) < ctxChars + 30) startCtx--;
      while (endCtx < t.content.length && /\S/.test(t.content.charAt(endCtx)) && (endCtx - (idx + matchLen)) < ctxChars + 30) endCtx++;
      var before = t.content.slice(startCtx, idx);
      var hit = t.content.slice(idx, idx + matchLen);
      var after = t.content.slice(idx + matchLen, endCtx);
      hits.push({
        index: idx,
        before: before,
        match: hit,
        after: after,
        truncatedStart: startCtx > 0,
        truncatedEnd: endCtx < t.content.length,
      });
      totalHits++;
      // Safety cap per template to avoid pathological results
      // (e.g., searching for "a" — would produce thousands of hits per doc).
      if (hits.length >= 200) break;
      // Advance re.lastIndex if the match was zero-length (paranoia).
      if (match[0].length === 0) re.lastIndex++;
    }
    if (hits.length) {
      results.push({
        id: t.id, name: t.name, category: t.category,
        contentLength: t.length,
        totalLength: t.length,
        hits: hits,
        totalHits: hits.length,
        capped: hits.length === 200,
      });
    }
  });
  // Sort by hit count desc (most relevant first), then by name.
  results.sort(function (a, b) {
    if (a.totalHits !== b.totalHits) return b.totalHits - a.totalHits;
    return String(a.name).localeCompare(String(b.name));
  });
  return { templates: results, totalHits: totalHits, totalTemplatesSearched: templates.length };
}

functions._tsRecordHistory:
function _tsRecordHistory(query, opts, hitCount) {
  if (!query) return;
  var s = window._tsSearcherState = window._tsSearcherState ||
    { templates: null, loadedAt: 0, loadPromise: null, history: [], CACHE_TTL_MS: 5 * 60 * 1000 };
  var entry = { query: query, opts: opts || {}, ts: Date.now(), hitCount: hitCount };
  s.history = [entry].concat(
    s.history.filter(function (h) { return h.query !== query; })
  ).slice(0, 5);
  try {
    window.eli.compat.lsSet("_template_searcher_history", JSON.stringify(s.history));
  } catch (_) {}
}

functions._tsLoadHistory:
function _tsLoadHistory() {
  var s = window._tsSearcherState = window._tsSearcherState ||
    { templates: null, loadedAt: 0, loadPromise: null, history: [], CACHE_TTL_MS: 5 * 60 * 1000 };
  try {
    var raw = window.eli.compat.lsGet("_template_searcher_history");
    if (raw) s.history = JSON.parse(raw) || [];
  } catch (_) { s.history = []; }
}

functions._tsRenderResults:
function _tsRenderResults(host, query, results) {
  if (!host) return;
  if (!query) {
    host.innerHTML =
      '<div class="_ts_empty">' +
        '<div class="_ts_empty_icon">🔎</div>' +
        '<div class="_ts_empty_title">Search your templates</div>' +
        '<div class="_ts_empty_sub">Find any word or phrase across every template in your library.</div>' +
        '<div class="_ts_empty_examples">' +
          '<span class="_ts_empty_label">Try:</span> ' +
          ['liability', 'indemnif', 'termination', 'governing law', 'auto-renew', 'exclusiv', 'force majeure'].map(function (q) {
            return '<button class="_ts_chip_btn" data-suggest="' + _tsEsc(q) + '">' + _tsEsc(q) + '</button>';
          }).join('') +
        '</div>' +
      '</div>';
    return;
  }
  if (results.error) {
    host.innerHTML = '<div class="_ts_empty">' +
      '<div class="_ts_empty_icon">⚠️</div>' +
      '<div class="_ts_empty_title">Invalid search pattern</div>' +
      '<div class="_ts_empty_sub">' + _tsEsc(results.error) + '</div>' +
    '</div>';
    return;
  }
  if (!results.templates.length) {
    host.innerHTML = '<div class="_ts_empty">' +
      '<div class="_ts_empty_icon">∅</div>' +
      '<div class="_ts_empty_title">No matches for <em>' + _tsEsc(query) + '</em></div>' +
      '<div class="_ts_empty_sub">Searched ' + results.totalTemplatesSearched + ' template' +
        (results.totalTemplatesSearched === 1 ? '' : 's') + '.</div>' +
    '</div>';
    return;
  }
  var summaryHtml = '<div class="_ts_summary">' +
    '<span class="_ts_summary_count">' + results.totalHits + '</span> ' +
    'match' + (results.totalHits === 1 ? '' : 'es') + ' across ' +
    '<strong>' + results.templates.length + '</strong> of ' +
    results.totalTemplatesSearched + ' templates' +
  '</div>';
  var cardsHtml = results.templates.map(function (t, ti) {
    var openByDefault = ti === 0; // First result open by default
    var hitsHtml = t.hits.map(function (h, hi) {
      return '<div class="_ts_hit">' +
        '<div class="_ts_hit_snippet">' +
          (h.truncatedStart ? '<span class="_ts_hit_ellipsis">…</span>' : '') +
          _tsEsc(h.before) +
          '<mark class="_ts_hit_mark">' + _tsEsc(h.match) + '</mark>' +
          _tsEsc(h.after) +
          (h.truncatedEnd ? '<span class="_ts_hit_ellipsis">…</span>' : '') +
        '</div>' +
        '<div class="_ts_hit_meta">' +
          '<span>Position ' + h.index.toLocaleString() + '</span>' +
          '<button class="_ts_hit_expand" data-template-id="' + _tsEsc(t.id) + '" data-hit-idx="' + hi + '">↗ View full clause</button>' +
        '</div>' +
      '</div>';
    }).join('');
    return '<details class="_ts_card"' + (openByDefault ? ' open' : '') + '>' +
      '<summary class="_ts_card_head">' +
        '<div class="_ts_card_title_wrap">' +
          '<span class="_ts_card_title">' + _tsEsc(t.name) + '</span>' +
          (t.category ? '<span class="_ts_card_category">' + _tsEsc(t.category) + '</span>' : '') +
        '</div>' +
        '<span class="_ts_card_count">' + t.totalHits + (t.capped ? '+' : '') + ' match' + (t.totalHits === 1 ? '' : 'es') + '</span>' +
      '</summary>' +
      '<div class="_ts_card_body">' + hitsHtml + '</div>' +
    '</details>';
  }).join('');
  host.innerHTML = summaryHtml + '<div class="_ts_cards">' + cardsHtml + '</div>';
}

functions._tsRenderHistory:
function _tsRenderHistory(host) {
  if (!host) return;
  var s = window._tsSearcherState || { history: [] };
  if (!s.history.length) { host.innerHTML = ''; return; }
  host.innerHTML = '<span class="_ts_history_label">Recent:</span> ' +
    s.history.map(function (h) {
      var hit = h.hitCount === 0
        ? '<span style="color:#94a3b8;">0</span>'
        : '<span style="color:#15803d;font-weight:700;">' + h.hitCount + '</span>';
      return '<button class="_ts_chip_btn" data-suggest="' + _tsEsc(h.query) + '" title="' + hit + ' previous matches">' +
        _tsEsc(h.query) +
        ' <span style="font-size:9px;opacity:0.7;">(' + h.hitCount + ')</span>' +
      '</button>';
    }).join('');
}

functions._tsShowFullClause:
function _tsShowFullClause(template, hitIdx) {
  if (!template || !template.hits[hitIdx]) return;
  if (typeof showEliDialog !== "function") return;
  var s = window._tsSearcherState;
  if (!s || !s.templates) return;
  var rec = s.templates.filter(function (t) { return t.id === template.id; })[0];
  if (!rec) return;
  var hit = template.hits[hitIdx];
  // Expand outward to nearest paragraph break (double newline or end of line).
  var content = rec.content;
  var start = hit.index;
  var end = hit.index + hit.match.length;
  // Walk backward to find paragraph start.
  while (start > 0) {
    var ch = content.charAt(start - 1);
    if (ch === "\n" && content.charAt(start - 2) === "\n") break;
    if (start < hit.index - 1500) break; // cap at ~1500 chars before
    start--;
  }
  while (end < content.length) {
    var ch2 = content.charAt(end);
    if (ch2 === "\n" && content.charAt(end + 1) === "\n") break;
    if (end > hit.index + hit.match.length + 1500) break;
    end++;
  }
  var clause = content.slice(start, end).trim();
  // Highlight ALL occurrences of the match within the extracted clause.
  var clauseHtml = _tsEsc(clause);
  // Use a raw regex on the escaped string — escape the match text for the regex too.
  var matchEscapedForRegex = hit.match.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  var highlightRe = new RegExp(matchEscapedForRegex, "gi");
  clauseHtml = clauseHtml.replace(highlightRe, function (m) {
    return '<mark class="_ts_hit_mark">' + m + '</mark>';
  });
  showEliDialog({
    variant: "neutral", icon: "📜",
    title: "Clause — " + template.name,
    body:
      '<div style="font-size:11px;color:#64748b;margin-bottom:10px;">' +
        '<code>' + _tsEsc(template.id) + '</code> · position ' + hit.index.toLocaleString() +
        ' · clause length ' + clause.length.toLocaleString() + ' chars' +
      '</div>' +
      '<div style="font:14px/1.6 Georgia, serif;color:#0f172a;white-space:pre-wrap;max-height:60vh;overflow-y:auto;padding:12px;background:#fafbfc;border:1px solid #e2e8f0;border-radius:4px;">' +
        clauseHtml +
      '</div>',
    buttons: [
      { label: "Copy to clipboard", cls: "btn-secondary",
        onclick: function () {
          try { navigator.clipboard.writeText(clause); }
          catch (_) {}
          if (typeof showToast === "function") showToast("Copied clause to clipboard", "ok");
        } },
      { label: "Close", cls: "btn-action btn-primary",
        onclick: function (e, ov) { if (ov && ov.parentNode) ov.parentNode.removeChild(ov); } },
    ],
  });
}

functions.showTemplateSearcher:
function showTemplateSearcher() {
  var out = window.eli && window.eli.ui && window.eli.ui.claimOutput
    ? window.eli.ui.claimOutput()
    : document.getElementById("output");
  if (!out) return;
  _tsLoadHistory();
  out.classList.add("eli-view-enter");
  out.innerHTML =
    '<div class="_ts_root">' +
      '<div class="_ts_header">' +
        '<div>' +
          '<div class="_ts_header_eyebrow">ADMIN — RESTRICTED</div>' +
          '<div class="_ts_header_title">🔎 Template Searcher</div>' +
          '<div class="_ts_header_sub" id="_ts_status">Loading templates…</div>' +
        '</div>' +
        '<div class="_ts_header_btns">' +
          '<button class="_ts_btn _ts_btn_platinum" id="_ts_refresh">↻ Reload</button>' +
        '</div>' +
      '</div>' +
      '<div class="_ts_search_panel">' +
        '<div class="_ts_search_row">' +
          '<div class="_ts_search_wrap">' +
            '<span class="_ts_search_icon">🔎</span>' +
            '<input type="text" id="_ts_input" placeholder="Search across all templates…" autocomplete="off">' +
            '<button class="_ts_search_clear" id="_ts_clear" title="Clear">×</button>' +
          '</div>' +
          '<button class="_ts_search_go _ts_btn_gold" id="_ts_go">Search</button>' +
        '</div>' +
        '<div class="_ts_options_row">' +
          '<label class="_ts_opt"><input type="checkbox" id="_ts_opt_case"> Case sensitive</label>' +
          '<label class="_ts_opt"><input type="checkbox" id="_ts_opt_word"> Whole word</label>' +
          '<span class="_ts_opt_spacer"></span>' +
          '<div class="_ts_history" id="_ts_history"></div>' +
        '</div>' +
      '</div>' +
      '<div class="_ts_results" id="_ts_results">' +
        '<div class="_ts_loading">' +
          '<span class="_ts_spinner"></span> Loading templates from storage…' +
        '</div>' +
      '</div>' +
    '</div>';
  var input = out.querySelector("#_ts_input");
  var clearBtn = out.querySelector("#_ts_clear");
  var goBtn = out.querySelector("#_ts_go");
  var refreshBtn = out.querySelector("#_ts_refresh");
  var optCase = out.querySelector("#_ts_opt_case");
  var optWord = out.querySelector("#_ts_opt_word");
  var resultsEl = out.querySelector("#_ts_results");
  var statusEl = out.querySelector("#_ts_status");
  var historyEl = out.querySelector("#_ts_history");
  var _lastResults = null;
  function _state() {
    if (!window._tsSearcherState) {
      window._tsSearcherState = { templates: null, loadedAt: 0, loadPromise: null, history: [], CACHE_TTL_MS: 5 * 60 * 1000 };
    }
    return window._tsSearcherState;
  }
  function _runSearch() {
    var query = input.value.trim();
    var s = _state();
    if (!s.templates) {
      tsLoadTemplates().then(function () { _runSearch(); });
      return;
    }
    var opts = { caseSensitive: optCase.checked, wholeWord: optWord.checked };
    var results = tsSearch(s.templates, query, opts);
    _lastResults = results;
    _tsRenderResults(resultsEl, query, results);
    if (query) _tsRecordHistory(query, opts, results.totalHits);
    _tsRenderHistory(historyEl);
  }
  function _setStatus(text) { statusEl.textContent = text; }
  function _loadAndRender(force) {
    if (force) _state().templates = null;
    _setStatus("Loading templates…");
    tsLoadTemplates(force).then(function (tpls) {
      var totalLen = tpls.reduce(function (a, t) { return a + (t.length || 0); }, 0);
      var compCount = tpls.filter(function (t) { return t.compressed; }).length;
      var ooxmlCount = tpls.filter(function (t) { return t.isOoxml; }).length;
      _setStatus(tpls.length + " template" + (tpls.length === 1 ? "" : "s") + " · " +
        Math.round(totalLen / 1024) + " KB readable text · " +
        compCount + " compressed · " +
        ooxmlCount + " stripped from OOXML");
      _tsRenderHistory(historyEl);
      if (input.value.trim()) _runSearch();
      else _tsRenderResults(resultsEl, "", null);
    }).catch(function (err) {
      _setStatus("Load failed: " + (err && err.message || "unknown"));
      resultsEl.innerHTML = '<div class="_ts_empty">' +
        '<div class="_ts_empty_icon">⚠️</div>' +
        '<div class="_ts_empty_title">Could not load templates</div>' +
        '<div class="_ts_empty_sub">' + _tsEsc(err && err.message || "unknown error") + '</div>' +
      '</div>';
    });
  }
  // Wire events
  goBtn.onclick = _runSearch;
  refreshBtn.onclick = function () { _loadAndRender(true); };
  clearBtn.onclick = function () {
    input.value = "";
    input.focus();
    _tsRenderResults(resultsEl, "", null);
  };
  input.onkeydown = function (ev) {
    if (ev.key === "Enter") { ev.preventDefault(); _runSearch(); }
    if (ev.key === "Escape") { input.value = ""; _tsRenderResults(resultsEl, "", null); }
  };
  optCase.onchange = _runSearch;
  optWord.onchange = _runSearch;
  out.onclick = function (ev) {
    var t = ev.target;
    var sugg = t.getAttribute && t.getAttribute("data-suggest");
    if (sugg) {
      input.value = sugg;
      input.focus();
      _runSearch();
      return;
    }
    var tid = t.getAttribute && t.getAttribute("data-template-id");
    if (tid) {
      var hitIdx = Number(t.getAttribute("data-hit-idx"));
      var tmpl = _lastResults && _lastResults.templates.filter(function (x) { return x.id === tid; })[0];
      if (tmpl) _tsShowFullClause(tmpl, hitIdx);
      return;
    }
  };
  _loadAndRender(false);
  setTimeout(function () { try { input.focus(); } catch (_) {} }, 100);
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.tools) return;

  function _show() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedTemplateSearcher"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showTemplateSearcher !== "function") {
      eli.log.event("tool", "template_searcher_fn_missing", {});
      if (typeof showToast === "function") showToast("Template Searcher failed to load", "err");
      return;
    }
    try { window.showTemplateSearcher(); }
    catch (e) {
      eli.log.event("tool", "template_searcher_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }

  eli.register({
    tile: { app_template_searcher: _show },
    template_searcher: { open: _show },
  });

  eli.log.event("tool", "template_searcher_initialized", {});
}

