/* template_searcher — premium search UI for bd_templates.
   Class prefix `_ts_`. Single accent: gold #c9a227 (project default).
   Three colors: navy/slate text, slate neutrals, single gold accent. */

._ts_root {
  font-family: Inter, "Segoe UI", system-ui, sans-serif;
  color: #0f172a;
  background: #f8fafc;
  padding: 0 0 32px 0;
  min-height: 100%;
}

/* ─── Header ───────────────────────────────────────────────────── */
._ts_header {
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #fff;
  padding: 20px 24px;
  border-bottom: 3px solid #c9a227;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
._ts_header_eyebrow {
  font: 800 9px/1 Inter, sans-serif;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: #c9a227;
  margin-bottom: 6px;
}
._ts_header_title {
  font: 800 24px/1.1 "Book Antiqua", Georgia, serif;
  margin: 0;
  letter-spacing: -0.2px;
}
._ts_header_sub {
  font-size: 11px;
  color: rgba(255,255,255,0.72);
  margin-top: 6px;
  font-weight: 500;
}
._ts_header_btns { display: flex; gap: 8px; }

._ts_btn {
  padding: 9px 14px;
  font: 800 10px/1 Inter, sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  border: none;
  cursor: pointer;
  transition: filter 0.15s, transform 0.05s;
}
._ts_btn:active { transform: translateY(1px); }
._ts_btn_platinum {
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  color: #334155;
  border: 1px solid #cbd5e1;
}
._ts_btn_platinum:hover { filter: brightness(0.97); }
._ts_btn_gold {
  background: linear-gradient(180deg, #d4af37 0%, #c9a227 100%);
  color: #0d1b2a;
  font-weight: 800;
  box-shadow: 0 1px 0 rgba(0,0,0,0.06);
}
._ts_btn_gold:hover { filter: brightness(1.04); }

/* ─── Search panel ─────────────────────────────────────────────── */
._ts_search_panel {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  margin: 18px 18px 0 18px;
  padding: 16px 18px 12px 18px;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.04);
}
._ts_search_row {
  display: flex;
  gap: 10px;
  align-items: stretch;
}
._ts_search_wrap {
  flex: 1;
  position: relative;
  display: flex;
  align-items: center;
  background: #fafbfc;
  border: 2px solid #cbd5e1;
  border-radius: 6px;
  transition: border-color 0.15s, background 0.15s;
}
._ts_search_wrap:focus-within {
  border-color: #c9a227;
  background: #fff;
  box-shadow: 0 0 0 4px rgba(201, 162, 39, 0.12);
}
._ts_search_icon {
  padding: 0 4px 0 14px;
  font-size: 16px;
  color: #64748b;
  user-select: none;
}
._ts_search_wrap input {
  flex: 1;
  border: 0;
  outline: 0;
  padding: 12px 10px;
  font: 600 14px/1.2 Inter, sans-serif;
  background: transparent;
  color: #0f172a;
  min-width: 0;
}
._ts_search_wrap input::placeholder { color: #94a3b8; font-weight: 500; }
._ts_search_clear {
  background: transparent;
  border: 0;
  color: #94a3b8;
  font-size: 22px;
  line-height: 1;
  padding: 0 14px 0 6px;
  cursor: pointer;
  display: flex;
  align-items: center;
}
._ts_search_clear:hover { color: #475569; }
._ts_search_go {
  padding: 0 22px;
  font: 800 12px/1 Inter, sans-serif;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  border-radius: 6px;
  cursor: pointer;
}
._ts_options_row {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 12px;
  flex-wrap: wrap;
}
._ts_opt {
  display: flex;
  align-items: center;
  gap: 6px;
  font: 600 11px/1 Inter, sans-serif;
  color: #475569;
  cursor: pointer;
  user-select: none;
}
._ts_opt input[type="checkbox"] {
  cursor: pointer;
  accent-color: #c9a227;
}
._ts_opt_spacer { flex: 1; }
._ts_history {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  justify-content: flex-end;
}
._ts_history_label {
  font: 700 10px/1 Inter, sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: #94a3b8;
}
._ts_chip_btn {
  padding: 4px 10px;
  font: 600 11px/1.2 Inter, sans-serif;
  background: #fef9e7;
  color: #92400e;
  border: 1px solid #fde68a;
  border-radius: 999px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
._ts_chip_btn:hover {
  background: #fef3c7;
  border-color: #facc15;
}

/* ─── Results ──────────────────────────────────────────────────── */
._ts_results {
  margin: 18px;
}

._ts_loading {
  padding: 32px 24px;
  text-align: center;
  font-size: 12px;
  color: #64748b;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
}
._ts_spinner {
  display: inline-block;
  width: 12px;
  height: 12px;
  border: 2px solid #e2e8f0;
  border-top-color: #c9a227;
  border-radius: 50%;
  animation: _ts_spin 0.8s linear infinite;
  margin-right: 8px;
  vertical-align: middle;
}
@keyframes _ts_spin { to { transform: rotate(360deg); } }

._ts_empty {
  padding: 48px 24px;
  text-align: center;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
}
._ts_empty_icon {
  font-size: 48px;
  margin-bottom: 12px;
  opacity: 0.85;
}
._ts_empty_title {
  font: 700 16px/1.3 "Book Antiqua", Georgia, serif;
  color: #0f172a;
  margin-bottom: 6px;
}
._ts_empty_title em {
  font-family: ui-monospace, Consolas, monospace;
  font-style: normal;
  background: #fef3c7;
  color: #92400e;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 0.92em;
}
._ts_empty_sub {
  font-size: 12px;
  color: #64748b;
  margin-bottom: 18px;
}
._ts_empty_examples {
  display: flex;
  gap: 6px;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
}
._ts_empty_label {
  font: 700 10px/1 Inter, sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: #94a3b8;
  margin-right: 4px;
}

._ts_summary {
  font: 600 12px/1.4 Inter, sans-serif;
  color: #475569;
  margin-bottom: 12px;
  padding: 10px 14px;
  background: #fafbfc;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #c9a227;
  border-radius: 4px;
}
._ts_summary_count {
  font-weight: 800;
  color: #0f172a;
  font-size: 14px;
}

._ts_cards {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

._ts_card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  overflow: hidden;
  transition: border-color 0.15s, box-shadow 0.15s;
}
._ts_card:hover { border-color: #cbd5e1; }
._ts_card[open] {
  border-color: #c9a227;
  box-shadow: 0 2px 8px rgba(201, 162, 39, 0.08);
}
._ts_card_head {
  cursor: pointer;
  user-select: none;
  padding: 12px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: linear-gradient(180deg, #fff 0%, #fafbfc 100%);
}
._ts_card[open] > ._ts_card_head {
  border-bottom: 1px solid #e2e8f0;
  background: linear-gradient(180deg, #fffdf5 0%, #fef9e7 100%);
}
._ts_card_head::-webkit-details-marker { display: none; }
._ts_card_head::marker { content: ""; }
._ts_card_title_wrap {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
._ts_card_title {
  font: 700 13px/1.3 Inter, sans-serif;
  color: #0f172a;
  overflow: hidden;
  text-overflow: ellipsis;
}
._ts_card_category {
  font: 600 9px/1 Inter, sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: #475569;
  background: #f1f5f9;
  padding: 3px 8px;
  border-radius: 3px;
}
._ts_card_count {
  font: 800 10px/1 Inter, sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: #0d1b2a;
  background: #c9a227;
  padding: 5px 10px;
  border-radius: 4px;
  white-space: nowrap;
}
._ts_card_body {
  padding: 0;
  display: flex;
  flex-direction: column;
}

._ts_hit {
  padding: 12px 16px;
  border-top: 1px solid #f1f5f9;
}
._ts_hit:first-child { border-top: 0; }
._ts_hit_snippet {
  font: 13px/1.65 Georgia, "Book Antiqua", serif;
  color: #1e293b;
  word-wrap: break-word;
}
._ts_hit_mark {
  background: #fef3c7;
  color: #92400e;
  font-weight: 700;
  padding: 1px 4px;
  border-radius: 3px;
  box-shadow: 0 1px 0 rgba(201, 162, 39, 0.3);
}
._ts_hit_ellipsis {
  color: #94a3b8;
  font-weight: 700;
  padding: 0 2px;
}
._ts_hit_meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 8px;
  font: 600 10px/1 Inter, sans-serif;
  color: #94a3b8;
  letter-spacing: 0.3px;
}
._ts_hit_expand {
  background: transparent;
  border: 1px solid #cbd5e1;
  color: #1565c0;
  padding: 4px 10px;
  font: 700 10px/1 Inter, sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  border-radius: 3px;
  cursor: pointer;
  transition: all 0.15s;
}
._ts_hit_expand:hover {
  border-color: #1565c0;
  background: #eff6ff;
}
